                   <div className="space-y-1">
                      <label className="text-[10px] font-bold uppercase text-slate-400">Time</label>
                      <div className="flex gap-2">
                        <input readOnly value={logForm.time} className={`flex-1 px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600' : 'bg-slate-50'}`} />
                        <button 
                          type="button"
                          onClick={() => setLogForm({...logForm, time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })})}
                          className="px-4 py-2 bg-blue-600 text-white rounded-xl text-[10px] font-black"
                        >
                          GET TIME
                        </button>
                      </div>
                   </div>
                </div>
                <div className="flex gap-3 pt-6">
                   <button type="button" onClick={()=>setShowLogModal(false)} className="flex-1 py-4 rounded-2xl bg-slate-100 text-slate-600 font-bold">Cancel</button>
                   <button type="submit" className="flex-1 py-4 rounded-2xl bg-blue-600 text-white font-black shadow-xl">Add Entry</button>
                </div>
             </form>
          </div>
        </div>
      )}

      {/* 4. Visitor Modal */}
      {showVisitorModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className={`w-full max-w-lg rounded-3xl p-8 shadow-2xl ${isDarkMode ? 'bg-gray-800' : 'bg-white'}`}>
             <h3 className="text-2xl font-black mb-6">{visitorType === 'meeting' ? 'Log Student Meeting' : 'Log General Visitor'}</h3>
             <form onSubmit={handleAddVisitor} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                   <div className="space-y-1">
                      <label className="text-[10px] font-bold uppercase text-slate-400">Visitor Name</label>
                      <input required value={visitorForm.name} onChange={e=>setVisitorForm({...visitorForm, name:e.target.value})} className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700 border-gray-600' : ''}`} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-bold uppercase text-slate-400">Mobile Number</label>
                      <input 
                        required 
                        type="tel"
                        maxLength={10}
                        value={visitorForm.number} 
                        onChange={e=>setVisitorForm({...visitorForm, number:e.target.value.replace(/\D/g, '')})} 
                        className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700 border-gray-600' : ''}`} 
                        placeholder="10-digit number"
                      />
                   </div>
                </div>

                {visitorType === 'meeting' ? (
                   <>
                      <div className="grid grid-cols-2 gap-4">
                         <div className="space-y-1">
                            <label className="text-[10px] font-bold uppercase text-slate-400">Select Student</label>
                            <select required value={visitorForm.studentName} onChange={e=>{
                              const a = allotments.find(x => x.studentName === e.target.value);
                              setVisitorForm({...visitorForm, studentName: e.target.value, roomNumber: a?.roomNumber || ''});
                            }} className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700 border-gray-600' : ''}`}>
                               <option value="">-- Choose Resident --</option>
                               {allotments.filter(a=>!a.leaveDate).map(a => <option key={a.id} value={a.studentName}>{a.studentName} (Room #{a.roomNumber})</option>)}
                            </select>
                         </div>
                         <div className="space-y-1">
                            <label className="text-[10px] font-bold uppercase text-slate-400">Relation</label>
                            <input value={visitorForm.relation} onChange={e=>setVisitorForm({...visitorForm, relation:e.target.value})} className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700 border-gray-600' : ''}`} placeholder="e.g. Father" />
                         </div>
                      </div>
                      <div className="space-y-1">
                         <label className="text-[10px] font-bold uppercase text-slate-400">Number of Members</label>
                         <input type="number" min="1" value={visitorForm.members} onChange={e=>setVisitorForm({...visitorForm, members:e.target.value})} className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700 border-gray-600' : ''}`} />
                      </div>
                   </>
                ) : (
                   <>
                      <div className="space-y-1">
                         <label className="text-[10px] font-bold uppercase text-slate-400">Purpose of Visit</label>
                         <textarea value={visitorForm.purpose} onChange={e=>setVisitorForm({...visitorForm, purpose:e.target.value})} className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700 border-gray-600' : ''}`} rows={2} />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[10px] font-bold uppercase text-slate-400">Address</label>
                         <input value={visitorForm.address} onChange={e=>setVisitorForm({...visitorForm, address:e.target.value})} className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700 border-gray-600' : ''}`} />
                      </div>
                   </>
                )}

                <div className="flex gap-3 pt-6">
                   <button type="button" onClick={()=>setShowVisitorModal(false)} className="flex-1 py-4 rounded-2xl bg-slate-100 text-slate-600 font-bold">Cancel</button>
                   <button type="submit" className="flex-1 py-4 rounded-2xl bg-blue-600 text-white font-black shadow-xl">Log Visitor (IN)</button>
                </div>
             </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';
import { useState, useMemo, useRef } from 'react';
import { libraryUtils, generateId } from '../utils/staffDataUtils';
import Papa from 'papaparse';

export default function StaffLibrary({ isDarkMode, showMessage, students = [], teachers = [], staffClassOptions = [] }) {
  const [activeSubTab, setActiveSubTab] = useState('inventory');
  const [refreshKey, setRefreshKey] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');
  const [readingSearch, setReadingSearch] = useState({ query: '', date: '' });
  const [studentSearch, setStudentSearch] = useState({ query: '', date: '' });
  const [teacherSearch, setTeacherSearch] = useState({ query: '', date: '' });

  // Modal States
  const [showBookModal, setShowBookModal] = useState(false);
  const [showReadingModal, setShowReadingModal] = useState(false);
  const [showStudentLendingModal, setShowStudentLendingModal] = useState(false);
  const [showTeacherLendingModal, setShowTeacherLendingModal] = useState(false);
  const [showReturnModal, setShowReturnModal] = useState(false);
  const [activeReturnId, setActiveReturnId] = useState(null);
  const [fineEntries, setFineEntries] = useState([]);
  const [currentFine, setCurrentFine] = useState({ reason: 'Late Return Fine', customReason: '', amount: 0 });
  const [returnDate, setReturnDate] = useState(new Date().toISOString().split('T')[0]);

  // Form States
  const [bookForm, setBookForm] = useState({ title: '', author: '', subject: 'Science', class: '10th', isbn: '', stock: 1 });
  const [readingForm, setReadingForm] = useState({ studentName: '', class: '', sec: '', bookId: '', bookSubject: '' });
  const [studentLendingForm, setStudentLendingForm] = useState({ studentName: '', class: '', sec: '', bookName: '', bookId: '', expectedReturnDate: '' });
  const [teacherLendingForm, setTeacherLendingForm] = useState({ teacherName: '', teacherSubject: '', bookSubject: '', bookId: '', expectedReturnDate: '' });

  const fileInputAddRef = useRef(null);
  const fileInputRemoveRef = useRef(null);

  // Data Fetching
  const books = useMemo(() => libraryUtils.getBooks(), [refreshKey]);
  const readingLogs = useMemo(() => libraryUtils.getReadingLogs(), [refreshKey]);
  const studentLending = useMemo(() => libraryUtils.getStudentLending(), [refreshKey]);
  const teacherLending = useMemo(() => libraryUtils.getTeacherLending(), [refreshKey]);

  // Filters
  const filteredBooks = books.filter(b => 
    b.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
    b.subject.toLowerCase().includes(searchQuery.toLowerCase()) ||
    b.class.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Handlers
  const handleSaveBook = (e) => {
    e.preventDefault();
    libraryUtils.saveBook(bookForm);
    setShowBookModal(false);
    setRefreshKey(k => k + 1);
    showMessage('Book record updated', 'success');
  };

  const handleReadingSession = (e) => {
    e.preventDefault();
    libraryUtils.addReadingLog(readingForm);
    setShowReadingModal(false);
    setRefreshKey(k => k + 1);
    showMessage('Reading session started', 'success');
  };

  const handleStudentLending = (e) => {
    e.preventDefault();
    libraryUtils.issueStudentBook(studentLendingForm);
    setShowStudentLendingModal(false);
    setRefreshKey(k => k + 1);
    showMessage('Book issued to student', 'success');
  };

  const handleTeacherLending = (e) => {
    e.preventDefault();
    libraryUtils.issueTeacherBook(teacherLendingForm);
    setShowTeacherLendingModal(false);
    setRefreshKey(k => k + 1);
    showMessage('Book issued to teacher', 'success');
  };

  const downloadSampleAdd = () => {
    const csv = "title,author,subject,class,id,stock\nScience Explorer,Dr. Smith,Quantum Physics,10th A,B-900@1,5\nHistory of India,R.K. Gupta,Medieval Era,12th C,H-200#X,3";
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'library_bulk_add_sample.csv'; a.click();
  };

  const downloadSampleRemove = () => {
    const csv = "id\nB-900@1\nH-200#X";
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'library_bulk_remove_sample.csv'; a.click();
  };

  const handleBulkAdd = (e) => {
    const file = e.target.files[0];
    if (file) {
      Papa.parse(file, {
        header: true,
        complete: (res) => {
          libraryUtils.bulkAddBooks(res.data);
          setRefreshKey(k => k + 1);
          showMessage(`Bulk added ${res.data.length} books`, 'success');
        }
      });
    }
  };

  const handleBulkRemove = (e) => {
    const file = e.target.files[0];
    if (file) {
      Papa.parse(file, {
        header: true,
        complete: (res) => {
          const ids = res.data.map(d => d.id).filter(i => i);
          libraryUtils.bulkRemoveBooks(ids);
          setRefreshKey(k => k + 1);
          showMessage(`Bulk removed ${ids.length} books`, 'success');
        }
      });
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      {/* 1. Header & Navigation */}
