                        <button onClick={() => { libraryUtils.deleteBook(b.id); setRefreshKey(k=>k+1); showMessage('Book removed','warning'); }} className="text-red-500 hover:underline font-bold text-xs">Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

