                        </div>
                      </div>
                    );
                  }
                  return null;
                })}
                {paginatedData.length === 0 && (
                  <div className={`text-center py-8 ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>No {detailListRole} found</div>
