              </>
            )}

          </div>

          {/* Action Buttons */}
          <div className={`sticky bottom-0 ${isDarkMode ? 'bg-gray-800 border-gray-700' : 'bg-white border-slate-200'} border-t mt-6 pt-4 flex justify-end gap-3`}>
            <button type="button" onClick={onClose} className={`px-4 py-2 border rounded-md font-medium transition ${isDarkMode ? 'border-gray-600 text-gray-300 hover:bg-gray-700' : 'border-slate-300 text-slate-700 hover:bg-slate-50'}`}>
              Cancel
            </button>
            <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 font-medium transition shadow-sm">
              Save Changes
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client';
import { useState, useMemo } from 'react';
import { transportUtils } from '../utils/staffDataUtils';

export default function UserTransportLog({ isDarkMode, user, showMessage }) {
  const [refreshKey, setRefreshKey] = useState(0);
  const [attendanceDate, setAttendanceDate] = useState(new Date().toISOString().split('T')[0]);

  const passengers = useMemo(() => transportUtils.getPassengers(), [refreshKey]);
  const vehicles   = useMemo(() => transportUtils.getVehicles(),   [refreshKey]);
  const attendanceLogs = useMemo(() => transportUtils.getAttendance(), [refreshKey, attendanceDate]);

  // Find the passenger record matching this user by name
  const myAssignment = useMemo(() =>
    passengers.find(p => p.name === user?.name || p.id === user?.id),
    [passengers, user]
  );

  const assignedBus = useMemo(() =>
    myAssignment ? vehicles.find(v => v.id === myAssignment.vehicleId) : null,
    [vehicles, myAssignment]
  );

  const handleToggle = (field) => {
    if (!myAssignment) return;
    transportUtils.toggleAttendance(attendanceDate, myAssignment.id, field);
    setRefreshKey(k => k + 1);
    if (showMessage) showMessage(
      field === 'boarded' ? '✅ Boarding recorded!' : '📍 Drop-off recorded!',
      'success'
    );
  };

  // Build a full history list from all log keys
  const myHistory = useMemo(() => {
    if (!myAssignment) return [];
    return Object.keys(attendanceLogs)
      .filter(key => key.endsWith(`_${myAssignment.id}`))
      .map(key => {
        const date = key.replace(`_${myAssignment.id}`, '');
        return { date, ...attendanceLogs[key] };
      })
      .sort((a, b) => new Date(b.date) - new Date(a.date));
  }, [attendanceLogs, myAssignment]);

  if (!myAssignment) {
    return (
      <div className={`p-12 rounded-[2.5rem] border text-center ${isDarkMode ? 'bg-gray-800 border-gray-700' : 'bg-white border-slate-100 shadow-xl'}`}>
        <div className="w-24 h-24 bg-slate-100 dark:bg-gray-700 rounded-full flex items-center justify-center text-5xl mx-auto mb-6">🚌</div>
        <h3 className={`text-2xl font-black mb-3 ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>No Bus Assigned</h3>
        <p className={`font-bold max-w-sm mx-auto ${isDarkMode ? 'text-gray-400' : 'text-slate-500'}`}>
          You are not assigned to any school transport route. Contact the transport office for registration.
        </p>
      </div>
    );
  }

  const primaryText   = isDarkMode ? 'text-white'    : 'text-slate-900';
  const secondaryText = isDarkMode ? 'text-gray-400' : 'text-slate-600';
  const labelText     = isDarkMode ? 'text-gray-500' : 'text-slate-400';

  const todayKey = `${attendanceDate}_${myAssignment.id}`;
  const todayLog = attendanceLogs[todayKey] || {
    boarded: false, dropped: false, boardingTime: '-', droppingTime: '-'
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">

      {/* Bus Info Banner */}
      <div className={`p-8 rounded-[2.5rem] border shadow-xl ${isDarkMode ? 'bg-gray-800 border-gray-700' : 'bg-white border-slate-100'}`}>

        {/* Header */}
        <div className="flex flex-wrap justify-between items-start gap-6 mb-10">
          <div className="flex items-center gap-4">
            <div className="w-16 h-16 rounded-3xl bg-blue-600 flex items-center justify-center text-3xl shadow-lg shadow-blue-600/30">
              🚌
            </div>
            <div>
              <h3 className={`text-2xl font-black ${primaryText}`}>{assignedBus?.busNumber || 'Assigned Bus'}</h3>
              <p className="text-blue-600 font-black uppercase tracking-widest text-[10px]">{assignedBus?.routeNumber || 'Route N/A'}</p>
              <p className={`text-xs font-bold mt-0.5 ${secondaryText}`}>Driver: {assignedBus?.driverName || '-'}</p>
            </div>
          </div>
          <div className="text-right">
            <p className={`text-[10px] font-black uppercase ${labelText}`}>Your Stop</p>
            <p className={`text-xl font-black ${primaryText}`}>{myAssignment.stop}</p>
          </div>
        </div>

        {/* Date selector */}
        <div className="flex justify-between items-center mb-6">
          <p className={`text-xs font-black uppercase ${labelText}`}>Log Date</p>
          <input
            type="date"
            value={attendanceDate}
            onChange={e => setAttendanceDate(e.target.value)}
            className={`px-4 py-2 rounded-xl border text-xs font-black ${isDarkMode ? 'bg-gray-900 border-gray-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`}
          />
        </div>

        {/* Action Buttons — Board & Drop */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

          {/* BOARD button */}
          <button
            onClick={() => handleToggle('boarded')}
            className={`group relative p-8 rounded-[2rem] border-2 text-left transition-all hover:scale-[1.02] active:scale-95 ${
              todayLog.boarded
                ? 'bg-emerald-500 border-emerald-500 text-white shadow-xl shadow-emerald-500/30'
                : `border-slate-200 dark:border-gray-700 ${isDarkMode ? 'bg-gray-900/50 hover:border-emerald-500' : 'bg-slate-50 hover:border-emerald-400 hover:bg-emerald-50'}`
            }`}
          >
            {todayLog.boarded && <div className="absolute top-4 right-4 text-2xl">✅</div>}
            <div className={`text-4xl mb-4 transition-transform group-hover:scale-110 ${todayLog.boarded ? '' : 'opacity-40 grayscale'}`}>🏠</div>
            <p className="text-sm font-black uppercase tracking-widest mb-1">Boarded / Picked Up</p>
            <p className={`text-[11px] font-bold ${todayLog.boarded ? 'text-emerald-100' : 'text-slate-400'}`}>
              {todayLog.boarded ? `Marked at ${todayLog.boardingTime}` : 'Tap when you board the bus'}
            </p>
          </button>

          {/* DROP button */}
          <button
            onClick={() => handleToggle('dropped')}
            className={`group relative p-8 rounded-[2rem] border-2 text-left transition-all hover:scale-[1.02] active:scale-95 ${
              todayLog.dropped
                ? 'bg-blue-600 border-blue-600 text-white shadow-xl shadow-blue-600/30'
                : `border-slate-200 dark:border-gray-700 ${isDarkMode ? 'bg-gray-900/50 hover:border-blue-600' : 'bg-slate-50 hover:border-blue-400 hover:bg-blue-50'}`
            }`}
          >
            {todayLog.dropped && <div className="absolute top-4 right-4 text-2xl">✅</div>}
            <div className={`text-4xl mb-4 transition-transform group-hover:scale-110 ${todayLog.dropped ? '' : 'opacity-40 grayscale'}`}>📍</div>
            <p className="text-sm font-black uppercase tracking-widest mb-1">Dropped / Reached Home</p>
            <p className={`text-[11px] font-bold ${todayLog.dropped ? 'text-blue-100' : 'text-slate-400'}`}>
              {todayLog.dropped ? `Marked at ${todayLog.droppingTime}` : 'Tap when you reach your destination'}
            </p>
          </button>
        </div>

        {/* Today's Summary Row */}
        {(todayLog.boarded || todayLog.dropped) && (
          <div className={`mt-8 p-5 rounded-2xl flex flex-wrap gap-6 justify-around ${isDarkMode ? 'bg-gray-900/60' : 'bg-slate-50'}`}>
            <div className="text-center">
              <p className={`text-[9px] font-black uppercase ${labelText}`}>Pickup Time</p>
              <p className={`text-xl font-black ${todayLog.boarded ? 'text-emerald-500' : secondaryText}`}>
                {todayLog.boardingTime || '-'}
              </p>
            </div>
            <div className="text-center">
              <p className={`text-[9px] font-black uppercase ${labelText}`}>Drop Time</p>
              <p className={`text-xl font-black ${todayLog.dropped ? 'text-blue-500' : secondaryText}`}>
                {todayLog.droppingTime || '-'}
              </p>
            </div>
          </div>
        )}

        {/* History Table */}
        <div className="mt-10 pt-10 border-t border-slate-100 dark:border-gray-700">
          <h4 className={`text-lg font-black mb-6 ${primaryText}`}>📖 Commute History (All Dates)</h4>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className={`text-[10px] font-black uppercase tracking-widest ${labelText}`}>
                  <th className="text-left py-3 px-2">Date</th>
                  <th className="text-center py-3 px-2">Boarded</th>
                  <th className="text-center py-3 px-2">Dropped</th>
                  <th className="text-right py-3 px-2">Pickup Time</th>
                  <th className="text-right py-3 px-2">Drop Time</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50 dark:divide-gray-700/50">
                {myHistory.map((log, i) => (
                  <tr key={i} className="hover:bg-slate-50 dark:hover:bg-gray-900/50 transition-all">
                    <td className={`py-4 px-2 text-sm font-black ${primaryText}`}>{log.date}</td>
                    <td className="py-4 px-2 text-center text-base">{log.boarded ? '✅' : '❌'}</td>
                    <td className="py-4 px-2 text-center text-base">{log.dropped ? '✅' : '❌'}</td>
                    <td className={`py-4 px-2 text-right text-xs font-black ${log.boarded ? 'text-emerald-500' : secondaryText}`}>
                      {log.boardingTime || '-'}
                    </td>
                    <td className={`py-4 px-2 text-right text-xs font-black ${log.dropped ? 'text-blue-500' : secondaryText}`}>
                      {log.droppingTime || '-'}
                    </td>
                  </tr>
                ))}
                {myHistory.length === 0 && (
                  <tr>
                    <td colSpan="5" className="py-12 text-center text-sm font-bold text-slate-400">
                      No commute history found yet. Start by clicking a button above!
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * CSV Import/Export utilities for Quiz Questions
 */

import Papa from 'papaparse';
import { generateId } from './quizDataUtils';

/**
 * Parse CSV content and convert to questions array
 * Expected format: Question,Option A,Option B,Option C,Option D,Correct Answer,Difficulty
 * Or: Question,Correct Answer (for short_answer and true_false)
 */
export const parseQuestionCsv = (csvContent) => {
  if (!csvContent || !csvContent.trim()) {
    return { success: false, questions: [], error: 'Empty CSV content' };
  }

  const result = Papa.parse(csvContent.trim(), {
    header: true,
    skipEmptyLines: true,
    transformHeader: (header) => header.trim()
  });

  if (result.errors.length > 0) {
    return { success: false, questions: [], error: result.errors[0].message };
  }

  const questions = [];
  const errors = [];

  result.data.forEach((row, index) => {
    try {
      const question = row['Question'] || row['question'];
      if (!question || !question.trim()) {
        errors.push(`Row ${index + 2}: Question text is required`);
        return;
      }

      const correctAnswer = row['Correct Answer'] || row['correct answer'];
      if (!correctAnswer || !correctAnswer.trim()) {
        errors.push(`Row ${index + 2}: Correct answer is required`);
        return;
      }

      // Determine question type based on available options
      const optionA = row['Option A'] || row['option a'];
      const optionB = row['Option B'] || row['option b'];
      const optionC = row['Option C'] || row['option c'];
      const optionD = row['Option D'] || row['option d'];

      let type = 'short_answer';
      const options = [];

      // If all options are present, it's likely an MCQ
      if (optionA && optionB && optionC && optionD) {
        type = 'mcq';
        options.push(
          { label: 'A', text: optionA.trim() },
          { label: 'B', text: optionB.trim() },
          { label: 'C', text: optionC.trim() },
          { label: 'D', text: optionD.trim() }
        );
      } else if (
        (correctAnswer.toLowerCase() === 'true' || correctAnswer.toLowerCase() === 'false') &&
        !optionC && !optionD
      ) {
        // Check if it's a true/false question
        type = 'true_false';
      }

      const difficulty = (row['Difficulty'] || row['difficulty'] || 'medium').toLowerCase();

      questions.push({
        id: generateId(),
        type,
        question: question.trim(),
        options: type === 'mcq' ? options : [],
        correctAnswer: correctAnswer.trim(),
        difficulty: ['easy', 'medium', 'hard'].includes(difficulty) ? difficulty : 'medium'
      });
    } catch (err) {
      errors.push(`Row ${index + 2}: ${err.message}`);
    }
  });

  if (questions.length === 0 && errors.length > 0) {
    return { success: false, questions: [], error: errors.join(', ') };
  }

  return {
    success: true,
    questions,
    warnings: errors.length > 0 ? errors : []
  };
};

/**
 * Generate CSV template for questions
 */
export const generateQuestionCsvTemplate = (type = 'all') => {
  const templates = {
    mcq: 'Question,Option A,Option B,Option C,Option D,Correct Answer,Difficulty\n"What is 2+2?","3","4","5","6","B","easy"\n"What is the capital of France?","London","Paris","Berlin","Rome","B","medium"',
    true_false: 'Question,Correct Answer,Difficulty\n"The earth is round.","True","easy"\n"Water boils at 100°C.","True","medium"',
    short_answer: 'Question,Correct Answer,Difficulty\n"What is the square root of 144?","12","medium"\n"Who wrote Romeo and Juliet?","Shakespeare","hard"',
    all: 'Question,Option A,Option B,Option C,Option D,Correct Answer,Difficulty\n"What is 2+2?","3","4","5","6","B","easy"\n"Is the earth round?","True","","","","True","easy"\n"What is 5×5?","20","25","30","35","B","medium"'
  };

  return templates[type] || templates.all;
};

/**
 * Export questions to CSV format
 */
export const exportQuestionsToCsv = (questions) => {
  const rows = questions.map(q => {
    const row = {
      Question: q.question,
      'Correct Answer': q.correctAnswer,
      Difficulty: q.difficulty || 'medium'
    };

    if (q.type === 'mcq' && q.options) {
      row['Option A'] = q.options[0]?.text || '';
      row['Option B'] = q.options[1]?.text || '';
      row['Option C'] = q.options[2]?.text || '';
      row['Option D'] = q.options[3]?.text || '';
    }

    return row;
  });

  return Papa.unparse(rows);
};

/**
 * Download questions as CSV file
 */
export const downloadQuestionsCsv = (questions, filename = 'questions.csv') => {
  if (!questions || questions.length === 0) {
    alert('No questions to download.');
    return;
  }

  const csv = exportQuestionsToCsv(questions);
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.setAttribute('download', filename);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

/**
 * Parse uploaded CSV file
 */
export const parseQuestionFile = (file) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    
    reader.onload = (e) => {
      const result = parseQuestionCsv(e.target.result);
      if (result.success) {
        resolve(result);
      } else {
        reject(new Error(result.error));
      }
    };
    
    reader.onerror = () => {
      reject(new Error('Error reading file'));
    };
    
    reader.readAsText(file);
  });
};

export default {
  parseQuestionCsv,
  generateQuestionCsvTemplate,
  exportQuestionsToCsv,
  downloadQuestionsCsv,
  parseQuestionFile
};

/**
 * LMS Quiz & Assessment Module - Data Utilities
 * Handles all quiz, question, and attempt data in localStorage
 */

// Local storage keys
const STORAGE_KEYS = {
  QUIZZES: 'lms_quizzes',
  ATTEMPTS: 'lms_attempts',
  QUESTIONS: 'lms_questions'
};

// Generate unique ID
export const generateId = () => Date.now() + Math.random().toString(36).substr(2, 9);

// Get quiz by ID
export const getQuizById = (quizId) => {
  const quizzes = getAllQuizzes();
  return quizzes.find(q => q.id === quizId);
};

// Get all quizzes
export const getAllQuizzes = () => {
  if (typeof window === 'undefined') return [];
  const stored = localStorage.getItem(STORAGE_KEYS.QUIZZES);
  return stored ? JSON.parse(stored) : [];
};

// Save quiz
export const saveQuiz = (quiz) => {
  if (typeof window === 'undefined') return;
  const quizzes = getAllQuizzes();
  const existingIndex = quizzes.findIndex(q => q.id === quiz.id);
  
  if (existingIndex !== -1) {
    quizzes[existingIndex] = { ...quizzes[existingIndex], ...quiz, updatedAt: new Date().toISOString() };
  } else {
    quizzes.push({ ...quiz, id: quiz.id || generateId(), createdAt: new Date().toISOString() });
  }
  
  localStorage.setItem(STORAGE_KEYS.QUIZZES, JSON.stringify(quizzes));
};

// Delete quiz
export const deleteQuiz = (quizId) => {
  if (typeof window === 'undefined') return;
  const quizzes = getAllQuizzes().filter(q => q.id !== quizId);
  localStorage.setItem(STORAGE_KEYS.QUIZZES, JSON.stringify(quizzes));
};

// Get questions for a quiz
export const getQuestionsForQuiz = (quizId) => {
  const quizzes = getAllQuizzes();
  const quiz = quizzes.find(q => q.id === quizId);
  return quiz?.questions || [];
};

// Save questions for a quiz
export const saveQuestionsForQuiz = (quizId, questions) => {
  if (typeof window === 'undefined') return;
  const quizzes = getAllQuizzes();
  const quizIndex = quizzes.findIndex(q => q.id === quizId);
  
  if (quizIndex !== -1) {
    quizzes[quizIndex].questions = questions;
    quizzes[quizIndex].updatedAt = new Date().toISOString();
    localStorage.setItem(STORAGE_KEYS.QUIZZES, JSON.stringify(quizzes));
  }
};

// Get all attempts
export const getAllAttempts = () => {
  if (typeof window === 'undefined') return [];
  const stored = localStorage.getItem(STORAGE_KEYS.ATTEMPTS);
  return stored ? JSON.parse(stored) : [];
};

// Get attempts for a student
export const getAttemptsForStudent = (studentId) => {
  return getAllAttempts().filter(a => a.studentId === studentId);
};

// Get attempts for a quiz
export const getAttemptsForQuiz = (quizId) => {
  return getAllAttempts().filter(a => a.quizId === quizId);
};

// Get attempt count for student on a quiz
export const getAttemptCount = (studentId, quizId) => {
  return getAllAttempts().filter(a => a.studentId === studentId && a.quizId === quizId).length;
};

// Save attempt
export const saveAttempt = (attempt) => {
  if (typeof window === 'undefined') return;
  const attempts = getAllAttempts();
  attempts.push({
    ...attempt,
    id: attempt.id || generateId(),
    attemptedAt: new Date().toISOString()
  });
  localStorage.setItem(STORAGE_KEYS.ATTEMPTS, JSON.stringify(attempts));
};

// Get quiz statistics for a specific quiz
export const getQuizStats = (quizId) => {
  const attempts = getAttemptsForQuiz(quizId);
  const totalAttempts = attempts.length;
  
  if (totalAttempts === 0) {
    return {
      totalAttempts: 0,
      averageScore: 0,
      highestScore: 0,
      lowestScore: 0,
      correctAnswers: 0,
      wrongAnswers: 0,
      passRate: 0
    };
  }
  
  const scores = attempts.map(a => a.score || 0);
  const averageScore = scores.reduce((a, b) => a + b, 0) / totalAttempts;
  const correctAnswers = attempts.reduce((acc, a) => acc + (a.correctAnswers || 0), 0);
  const wrongAnswers = attempts.reduce((acc, a) => acc + (a.wrongAnswers || 0), 0);
  
  return {
    totalAttempts,
    averageScore: Math.round(averageScore * 10) / 10,
    highestScore: Math.max(...scores),
    lowestScore: Math.min(...scores),
    correctAnswers,
    wrongAnswers,
    passRate: totalAttempts > 0 ? Math.round((correctAnswers / (correctAnswers + wrongAnswers)) * 100) : 0
  };
};

// Get student-wise performance
export const getStudentPerformance = (quizId) => {
  const attempts = getAttemptsForQuiz(quizId);
  const studentMap = new Map();
  
  attempts.forEach(attempt => {
    const existing = studentMap.get(attempt.studentId);
    if (!existing || attempt.score > existing.score) {
      studentMap.set(attempt.studentId, {
        studentId: attempt.studentId,
        studentName: attempt.studentName,
        score: attempt.score,
        totalQuestions: attempt.totalQuestions,
        correctAnswers: attempt.correctAnswers,
        wrongAnswers: attempt.wrongAnswers,
        attemptedAt: attempt.attemptedAt
      });
    }
  });
  
  return Array.from(studentMap.values()).sort((a, b) => b.score - a.score);
};

// Get leaderboard for a class
export const getLeaderboard = (className, limit = 3) => {
  const attempts = getAllAttempts();
  const studentMap = new Map();
  
  attempts.forEach(attempt => {
    const studentClass = attempt.className || attempt.studentClass;
    if (studentClass !== className) return;
    
    const existing = studentMap.get(attempt.studentId);
    if (!existing || attempt.score > existing.bestScore) {
      studentMap.set(attempt.studentId, {
        studentId: attempt.studentId,
        studentName: attempt.studentName,
        bestScore: attempt.score,
        totalQuestions: attempt.totalQuestions,
        attempts: 1
      });
    } else {
      existing.attempts += 1;
    }
  });
  
  return Array.from(studentMap.values())
    .sort((a, b) => b.bestScore - a.bestScore)
    .slice(0, limit);
};

// Get quizzes available for a student
export const getAvailableQuizzes = (studentClass, studentSection) => {
  const quizzes = getAllQuizzes();
  return quizzes.filter(q => {
    // Check if quiz is active
    if (q.status !== 'active') return false;
    // Check if class matches
    if (q.className && q.className !== studentClass) return false;
    // Check if section matches (if specified)
    if (q.section && q.section !== studentSection) return false;
    return true;
  });
};

// Initialize with sample data
export const initializeSampleQuizzes = () => {
  if (typeof window === 'undefined') return;
  if (getAllQuizzes().length > 0) return;
  
  const sampleQuizzes = [
    {
      id: generateId(),
      title: 'Math Basics Quiz',
      className: '10',
      section: 'A',
      subject: 'Mathematics',
      academicYear: '2024-25',
      board: 'CBSE',
      status: 'active',
      timer: 30, // minutes
      attemptLimit: 2,
      randomize: true,
      questions: [
        {
          id: generateId(),
          type: 'mcq',
          question: 'What is the value of 2 + 2?',
          options: ['3', '4', '5', '6'],
          correctAnswer: 'B',
          difficulty: 'easy'
        },
        {
          id: generateId(),
          type: 'mcq',
          question: 'What is 12 × 12?',
          options: ['124', '144', '134', '154'],
          correctAnswer: 'B',
          difficulty: 'medium'
        },
        {
          id: generateId(),
          type: 'true_false',
          question: 'Zero is a positive number.',
          correctAnswer: 'False',
          difficulty: 'easy'
        },
        {
          id: generateId(),
          type: 'short_answer',
          question: 'What is the square root of 144?',
          correctAnswer: '12',
          difficulty: 'medium'
        }
      ],
      createdAt: new Date().toISOString()
    },
    {
      id: generateId(),
      title: 'Science General Knowledge',
      className: '10',
      section: 'A',
      subject: 'Science',
      academicYear: '2024-25',
      board: 'CBSE',
      status: 'active',
      timer: 20,
      attemptLimit: 2,
      randomize: false,
      questions: [
        {
          id: generateId(),
          type: 'mcq',
          question: 'What is the chemical formula for water?',
          options: ['H2O', 'CO2', 'NaCl', 'O2'],
          correctAnswer: 'A',
          difficulty: 'easy'
        },
        {
          id: generateId(),
          type: 'mcq',
          question: 'Which planet is known as the Red Planet?',
          options: ['Venus', 'Mars', 'Jupiter', 'Saturn'],
          correctAnswer: 'B',
          difficulty: 'easy'
        }
      ],
      createdAt: new Date().toISOString()
    }
  ];
  
  localStorage.setItem(STORAGE_KEYS.QUIZZES, JSON.stringify(sampleQuizzes));
};

// Export functions
export default {
  generateId,
  getQuizById,
  getAllQuizzes,
  saveQuiz,
  deleteQuiz,
  getQuestionsForQuiz,
  saveQuestionsForQuiz,
  getAllAttempts,
  getAttemptsForStudent,
  getAttemptsForQuiz,
  getAttemptCount,
  saveAttempt,
  getQuizStats,
  getStudentPerformance,
  getLeaderboard,
  getAvailableQuizzes,
  initializeSampleQuizzes,
  STORAGE_KEYS
};

